def source(sid,school,stem,title,kind='scholarship',lang='zh',dom=False):
 r=json.loads((B/school/(stem+'.receipt.json')).read_text(encoding='utf-8'))
 textPath=r['textPath'];textSha=r['textSha256']
 if dom:
  dr=json.loads((B/school/(stem+'.dom-receipt.json')).read_text(encoding='utf-8'));textPath=dr['textPath'];textSha=dr['textSha256']
 s={'id':sid,'url':r['requestedUrl'],'title':title,'publisher':'Center for Language Education and Cooperation' if school=='central' else {'shnu':'Shanghai Normal University','snnu':'Shaanxi Normal University','blcu':'Beijing Language and Culture University'}[school],'kind':kind,'language':lang,'official':True,'accessedAt':'2026-10-19'}
